-- 검증(읽기 전용): ap_psychology. ok 가 모두 true 여야 한다.
select 'subject' as check, 1 as expected, (select count(*) from subjects where ap_subject_code = 'ap_psychology') as actual, 1 = (select count(*) from subjects where ap_subject_code = 'ap_psychology') as ok
union all
select 'edition' as check, 1 as expected, (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_psychology') and edition = 'ced-2027') as actual, 1 = (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_psychology') and edition = 'ced-2027') as ok
union all
